// Edit this list — one item per keyword/brand to scan.
const keywords = ['MentionFox', 'FoxAPIs', 'social listening n8n'];
return keywords.map(k => ({ json: { keyword: k } }));

// Flatten every scan response to one item per mention.
const out = [];
for (const it of items) {
  const r = it.json || {};
  const arr = r.mentions || r.results || r.items || [];
  for (const m of arr) out.push({ json: m });
}
return out;

// Dedupe across runs using workflow static data (cap the memory at 2000 urls).
const store = $getWorkflowStaticData('global');
const seen = new Set(store.seenUrls || []);
const fresh = [];
for (const it of items) {
  const m = it.json || {};
  const key = m.source_url || m.url || `${m.source_platform}:${m.found_at}:${(m.content||'').slice(0,60)}`;
  if (!seen.has(key)) { seen.add(key); fresh.push({ json: m }); }
}
store.seenUrls = Array.from(seen).slice(-2000);
return fresh;
